	private void removeInvalidArchives() {
		DataTypeManagerPlugin plugin = env.getPlugin(typeof(DataTypeManagerPlugin));
		ArchiveManager archiveManager = plugin.getArchiveManager();
		/* @SuppressWarnings("unchecked") */
		Map<UniversalID, InvalidArchive> invalid =
			(Map<UniversalID, InvalidArchive>) getInstanceField("invalidArchives",
				archiveManager);
		Collection<InvalidArchive> values = invalid.values();
		foreach (InvalidArchive invalidFileArchive in values) {
			removeInvalidArchive(archiveManager, invalidFileArchive);
		}
	}

	private void removeInvalidArchive(ArchiveManager archiveManager, InvalidArchive archive) {
		runSwing(() => archiveManager.closeInvalidArchive(archive));
	}

	private DataTypesProvider getVisibleProvider() {
		DockingWindowManager dwm = DockingWindowManager.getActiveInstance();
		List<DataTypesProvider> providers = dwm.getComponentProviders(typeof(DataTypesProvider));
		foreach (ComponentProvider provider in providers) {
			if (provider.isVisible()) {
				return (DataTypesProvider) provider;
			}
		}
		Assert.fail("Unable to find a visible provider");
		return null;// cannot get here
	}

	private DataTypeManager createChangedDatatypesFromArchive(List<DataTypeSyncInfo> list,
			Set<DataTypeSyncInfo> set) {
		DataTypeManager dtm = program.getDataTypeManager();

		DomainFolder rootFolder = env.getGhidraProject().getRootFolder();
		ProjectDataTypeArchive archive;
		try {
			archive = DataTypeArchiveFactory.createProjectArchive(rootFolder, "MyArchive", this);
		}
		catch (Exception e) {
			throw new RuntimeException(e);
		}
		DataTypeManager sourceDtm = archive.getDataTypeManager();

		StructureDataType sdt1 = new StructureDataType("MyDataType1", 0);
		sdt1.add(new PointerDataType(new StringDataType()), "name", null);
		sdt1.add(new IntegerDataType(), "age", null);
		sdt1.add(new PointerDataType(new VoidDataType()), "data", null);

		StructureDataType sdt2 = new StructureDataType("MyDataType2", 0);
		sdt2.add(new PointerDataType(new IntegerDataType()));
		sdt2.add(new IntegerDataType());
		sdt2.add(new WordDataType());

		int id = sourceDtm.startTransaction("Test");
		DataType dt1 = sourceDtm.addDataType(sdt1, null);
		DataType dt2 = sourceDtm.addDataType(sdt2, null);
		sourceDtm.endTransaction(id, true);

		tx(program, () => {

			Structure @struct = (Structure) dtm.addDataType(dt1, null);
			@struct.add(new IntegerDataType(), "id", null);
			Structure struct2 = (Structure) dtm.addDataType(dt2, null);
			struct2.add(new IntegerDataType());

			DataTypeSyncInfo sync1 = new DataTypeSyncInfo(@struct, sourceDtm);
			DataTypeSyncInfo sync2 = new DataTypeSyncInfo(struct2, sourceDtm);
			list.add(sync1);
			list.add(sync2);
			set.add(sync1);
		});

		return sourceDtm;
	}

	private void showModalDialogInTool(DialogComponentProvider dialog) {
		runSwing(() => tool.showDialog(dialog), false);

		waitForSwing();
	}

